132: func blockMessages(messages []Message) []messageBlock {
133: 	blocks := []messageBlock{}
134: 	for i := 0; i < len(messages); {
135: 		msg := messages[i]
136: 		if msg.Role == "assistant_tool_call" {
137: 			block := messageBlock{Messages: []Message{msg}}
138: 			if i+1 < len(messages) && messages[i+1].Role == "tool" && messages[i+1].CallID == msg.CallID {
139: 				block.Messages = append(block.Messages, messages[i+1])
140: 				i += 2
141: 			} else {
142: 				i++
143: 			}
144: 			blocks = append(blocks, block)
145: 			continue
146: 		}
147: 		block := messageBlock{Messages: []Message{msg}, Anchor: msg.Role == "user"}
148: 		blocks = append(blocks, block)
149: 		i++
150: 	}
151: 	return blocks
152: }
