171: func containsAnchor(blocks []messageBlock, anchor messageBlock) bool {
172: 	if len(anchor.Messages) == 0 {
173: 		return false
174: 	}
175: 	anchorContent := anchor.Messages[0].Content
176: 	for _, block := range blocks {
177: 		if len(block.Messages) > 0 && block.Messages[0].Role == "user" && block.Messages[0].Content == anchorContent {
178: 			return true
179: 		}
180: 	}
181: 	return false
182: }
