190: func expandLeadingToolExchange(selected, all []messageBlock) []messageBlock {
191: 	first := selected[0]
192: 	if !hasTrailingToolResult(first) || len(first.Messages) == 0 {
193: 		return selected
194: 	}
195: 	callID := first.Messages[0].CallID
196: 	if callID == "" {
197: 		return selected
198: 	}
199: 	for i := len(all) - 1; i >= 0; i-- {
200: 		block := all[i]
201: 		if len(block.Messages) == 0 || block.Messages[0].Role != "assistant_tool_call" {
202: 			continue
203: 		}
204: 		if block.Messages[0].CallID != callID {
205: 			continue
206: 		}
207: 		if containsBlock(selected, block) {
208: 			return selected
209: 		}
210: 		return append(selected, block)
211: 	}
212: 	return selected
213: }
