217: 		return false
218: 	}
219: 	for _, block := range blocks {
220: 		if len(block.Messages) == 0 {
221: 			continue
222: 		}
223: 		if block.Messages[0].Role == target.Messages[0].Role && block.Messages[0].CallID == target.Messages[0].CallID && block.Messages[0].Content == target.Messages[0].Content {
224: 			return true
225: 		}
226: 	}
227: 	return false
