121: func scanRepo(root string, maxFiles int) (map[string]int, []string, error) {
122: 	counts := map[string]int{}
123: 	markerSet := map[string]struct{}{}
124: 	markers := []string{"go.mod", "package.json", "pyproject.toml", "Cargo.toml", "Makefile"}
125: 	inspected := 0
126: 	err := filepath.Walk(root, func(path string, info os.FileInfo, err error) error {
127: 		if err != nil {
128: 			return err
129: 		}
130: 		if info.IsDir() {
131: 			if isIgnoredRepoDir(info.Name()) {
132: 				return filepath.SkipDir
133: 			}
134: 			return nil
135: 		}
136: 		inspected++
137: 		if inspected > maxFiles {
138: 			return filepath.SkipDir
139: 		}
140: 		base := filepath.Base(path)
141: 		for _, marker := range markers {
142: 			if base == marker {
143: 				markerSet[marker] = struct{}{}
144: 			}
145: 		}
146: 		ext := strings.ToLower(filepath.Ext(base))
147: 		if ext == "" {
148: 			ext = "[no extension]"
149: 		}
150: 		counts[ext]++
151: 		return nil
152: 	})
153: 	markerFiles := make([]string, 0, len(markerSet))
154: 	for marker := range markerSet {
155: 		markerFiles = append(markerFiles, marker)
156: 	}
157: 	sort.Strings(markerFiles)
158: 	return counts, markerFiles, err
