184: func summarizeExtensions(counts map[string]int, maxEntries int) string {
185: 	type pair struct {
186: 		Ext   string
187: 		Count int
188: 	}
189: 	total := 0
190: 	pairs := make([]pair, 0, len(counts))
191: 	for ext, count := range counts {
192: 		total += count
193: 		pairs = append(pairs, pair{Ext: ext, Count: count})
194: 	}
195: 	sort.Slice(pairs, func(i, j int) bool {
196: 		if pairs[i].Count == pairs[j].Count {
197: 			return pairs[i].Ext < pairs[j].Ext
198: 		}
199: 		return pairs[i].Count > pairs[j].Count
200: 	})
201: 	if len(pairs) > maxEntries {
202: 		pairs = pairs[:maxEntries]
203: 	}
204: 	parts := make([]string, 0, len(pairs))
205: 	for _, item := range pairs {
206: 		pct := 0
207: 		if total > 0 {
208: 			pct = int(float64(item.Count) / float64(total) * 100)
209: 		}
210: 		parts = append(parts, fmt.Sprintf("%s %d%%", item.Ext, pct))
211: 	}
212: 	return strings.Join(parts, ", ")
